package project.init.framework.authen;import project.init.framework.domain.BearerContext;public class BearerContextHolder {    private static final ThreadLocal<BearerContext> contextHolder = new ThreadLocal<>();    public static void remove() {        contextHolder.remove();    }    public static BearerContext get() {        BearerContext ctx = contextHolder.get();        if (ctx == null) {            ctx = new BearerContext();            contextHolder.set(ctx);        }        return ctx;    }}